// Money is stored as whole cents so 0.1 + 0.2 style errors never appear.
export function parseCents(text: string): number | null {
  const t = text.trim();
  if (!/^\d+(\.\d{1,2})?$/.test(t)) return null;
  const [whole, frac = ""] = t.split(".");
  const cents = parseInt(whole, 10) * 100 + parseInt(frac.padEnd(2, "0") || "0", 10);
  return cents > 0 ? cents : null;
}

export const asMoney = (cents: number) => (cents / 100).toFixed(2);

import { createContext, useContext, useEffect, useReducer, ReactNode } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";

export const CATEGORIES = ["Food", "Travel", "Bills", "Fun", "Other"] as const;
export type Category = (typeof CATEGORIES)[number];
export type Expense = { id: string; title: string; cents: number; category: Category };

type State = { items: Expense[]; loaded: boolean };
type Action =
  | { type: "load"; items: Expense[] }
  | { type: "add"; item: Expense }
  | { type: "remove"; id: string };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "load":
      return { items: action.items, loaded: true };
    case "add":
      return { ...state, items: [action.item, ...state.items] };
    case "remove":
      return { ...state, items: state.items.filter((e) => e.id !== action.id) };
  }
}

const KEY = "expenses.v1";
type Ctx = { state: State; dispatch: React.Dispatch<Action> };
const ExpenseContext = createContext<Ctx | null>(null);

export function ExpenseProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, { items: [], loaded: false });

  useEffect(() => {
    AsyncStorage.getItem(KEY)
      .then((raw) => dispatch({ type: "load", items: raw ? JSON.parse(raw) : [] }))
      .catch(() => dispatch({ type: "load", items: [] }));
  }, []);

  useEffect(() => {
    if (state.loaded) AsyncStorage.setItem(KEY, JSON.stringify(state.items));
  }, [state]);

  return <ExpenseContext.Provider value={{ state, dispatch }}>{children}</ExpenseContext.Provider>;
}

export function useExpenses() {
  const ctx = useContext(ExpenseContext);
  if (!ctx) throw new Error("useExpenses must be used inside ExpenseProvider");
  return ctx;
}

import { useMemo, useState } from "react";
import { SafeAreaView, View, Text, TextInput, Pressable, FlatList, StyleSheet } from "react-native";
import { CATEGORIES, Category, ExpenseProvider, useExpenses } from "./ExpenseContext";
import { asMoney, parseCents } from "./money";

function Screen() {
  const { state, dispatch } = useExpenses();
  const [title, setTitle] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState<Category>("Food");
  const [error, setError] = useState("");

  const total = useMemo(() => state.items.reduce((s, e) => s + e.cents, 0), [state.items]);
  const byCategory = useMemo(() => {
    const map = new Map<Category, number>();
    state.items.forEach((e) => map.set(e.category, (map.get(e.category) ?? 0) + e.cents));
    return [...map.entries()];
  }, [state.items]);

  const add = () => {
    const cents = parseCents(amount);
    if (!title.trim() || cents === null) {
      setError("Enter a title and an amount such as 12.50");
      return;
    }
    setError("");
    dispatch({ type: "add", item: { id: Date.now().toString(), title: title.trim(), cents, category } });
    setTitle("");
    setAmount("");
  };

  return (
    <SafeAreaView style={styles.screen}>
      <Text style={styles.total}>{asMoney(total)}</Text>
      <Text style={styles.sub}>Total spent</Text>

      <TextInput style={styles.input} value={title} onChangeText={setTitle} placeholder="Title" />
      <TextInput
        style={styles.input}
        value={amount}
        onChangeText={setAmount}
        placeholder="Amount"
        keyboardType="decimal-pad"
      />
      <View style={styles.chips}>
        {CATEGORIES.map((c) => (
          <Pressable key={c} onPress={() => setCategory(c)} style={[styles.chip, c === category && styles.chipOn]}>
            <Text style={c === category ? styles.chipTextOn : undefined}>{c}</Text>
          </Pressable>
        ))}
      </View>
      {!!error && <Text style={styles.error}>{error}</Text>}
      <Pressable style={styles.button} onPress={add}>
        <Text style={styles.buttonText}>Add expense</Text>
      </Pressable>

      {byCategory.map(([c, cents]) => (
        <Text key={c} style={styles.summary}>
          {c}: {asMoney(cents)}
        </Text>
      ))}

      <FlatList
